const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = v => JSON.parse(JSON.stringify(v));
const uuid = () => crypto.randomUUID();
const CSV_COLUMNS=['recipe_key','recipe_name','recipe_type','station','yield_quantity','yield_unit','input_quantity','input_unit','portion_quantity','portion_unit','shelf_life','method','recipe_notes','track_trim','is_butchery','ingredient_name','ingredient_source','ingredient_id','component_recipe_key','quantity','unit','ingredient_note','target_prep_item_id'];
const csvName=v=>String(v||'').normalize('NFKC').trim().replace(/\s+/g,' ').toLowerCase();
const csvNumber=v=>{const s=String(v??'').trim();return /^(?:\d+(?:\.\d*)?|\.\d+)$/.test(s)&&Number.isFinite(Number(s))&&Number(s)>0?Number(s):null;};
const freshCSV=()=>({id:uuid(),items:[],selected:0,visible:false,fileName:'',restaurantId:null});
function parseRecipeCSV(text){
 if(typeof text!=='string'||text.length>5000000)throw new Error('CSV must be under 5 MB.');
 text=text.replace(/^\uFEFF/,'');let rows=[],row=[],value='',quoted=false,closed=false,line=1,start=1;
 const cell=()=>{row.push(value);value='';closed=false;};const finish=()=>{cell();if(row.some(v=>v.trim()))rows.push({cells:row,line:start});row=[];start=line+1;};
 for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){value+='"';i++;}else{quoted=false;closed=true;}}else{if(c==='\r'){if(text[i+1]==='\n')i++;value+='\n';line++;}else{value+=c;if(c==='\n')line++;}}continue;}
  if(c==='"'){if(value||closed)throw new Error('Unexpected quote at CSV line '+line+'.');quoted=true;}
  else if(c===',')cell();else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;finish();line++;}
  else{if(closed)throw new Error('Text after a closing quote at CSV line '+line+'.');value+=c;}
  if(rows.length>5000)throw new Error('Use at most 5,000 CSV rows per upload.');
 }
 if(quoted)throw new Error('Unclosed quoted field at CSV line '+start+'.');if(value||row.length||closed)finish();
 if(rows.length<2)throw new Error('CSV needs a header and at least one ingredient row.');
 const headers=rows.shift().cells.map(v=>v.trim().toLowerCase());if(new Set(headers).size!==headers.length)throw new Error('CSV has duplicate headers.');
 for(const h of headers)if(!CSV_COLUMNS.includes(h))throw new Error('Unknown CSV column: '+h+'. Use the Recipe Studio template.');
 for(const h of ['recipe_key','recipe_name','recipe_type','station','yield_quantity','yield_unit','method','ingredient_name','quantity','unit'])if(!headers.includes(h))throw new Error('Missing CSV column: '+h+'.');
 const groups=new Map(),meta=CSV_COLUMNS.slice(1,15).concat('target_prep_item_id');
 for(const row of rows){if(row.cells.length!==headers.length)throw new Error('CSV line '+row.line+' has '+row.cells.length+' fields; expected '+headers.length+'.');const r=Object.fromEntries(headers.map((h,i)=>[h,row.cells[i].trim()]));
  if(!r.recipe_key)throw new Error('CSV line '+row.line+' needs recipe_key to identify its recipe.');
  if(!groups.has(r.recipe_key)){if(groups.size>=200)throw new Error('Use at most 200 recipes per upload.');groups.set(r.recipe_key,{key:r.recipe_key,meta:{},lines:[],errors:[],mode:'',targetId:'',reviewed:false,status:'review',cost:null});}
  const g=groups.get(r.recipe_key);for(const h of meta)if(r[h]){if(g.meta[h]&&g.meta[h]!==r[h])g.errors.push('Line '+row.line+': conflicting '+h+'. Correct the CSV and upload again.');else g.meta[h]=r[h];}
  if(g.lines.length>=1000)throw new Error('Recipe '+g.key+' has more than 1,000 ingredient rows.');
  g.lines.push({row:row.line,name:r.ingredient_name||'',source:r.ingredient_source||'',sourceId:r.ingredient_id||'',componentKey:r.component_recipe_key||'',amount:r.quantity||'',unit:r.unit||'',note:r.ingredient_note||'',link:null,match:''});
 }
 return [...groups.values()];
}
const csvTemplateText=()=> '\uFEFF'+CSV_COLUMNS.join(',')+'\r\n';

