const freshRecipeHistory = () => ({loaded:false,versions:[],selected:null,costs:[],jobs:[],currentKey:null,moreVersions:false,moreCosts:false,moreJobs:false,stale:false,trackingReturn:null});
const freshTracking = () => ({jobs:[],loaded:false,role:null,options:[],selected:null,form:{},dirty:false,preview:null,pending:null,uncertain:false,hasMore:false});
