 disconnectedCallback(){window.removeEventListener('beforeunload',this.leaveHandler);this.mounted=false;}
 async configure(config){
  if(this.busy||this.aiBusy||this.uncertain||this.tracking.uncertain)throw new Error('Wait for the current request to finish before changing connections.');
  if(this.hasUnsavedChanges() && this.config.restaurantId && config.restaurantId!==this.config.restaurantId)throw new Error('Save or export the open recipe before changing restaurants.');
  if(config.supabaseUrl && config.supabaseUrl!==PROJECT)throw new Error('This module is configured for Mise.Ai-0000.');
  const changed=this.config.restaurantId!==config.restaurantId;
  this.config=changed?{supabaseUrl:PROJECT,...config}:{...this.config,...config};
  if(changed){this.csv=freshCSV();this.data={recipes:[],raw_ingredients:[],batch_components:[],stations:STATIONS,units:UNITS.map(code=>({code,label:code}))};this.draft=fresh();this.pending=null;this.price=null;this.history=[];this.dirty=false;this.navigation=[];this.view='recipe';this.tracking=freshTracking();this.recipeHistory=freshRecipeHistory();}
  if(this.mounted){this.render();return this.reload();}
 }
 $(s){return this.shadowRoot.querySelector(s)}
 $$(s){return [...this.shadowRoot.querySelectorAll(s)]}
