 unitOptions(value,blank=false){let units=[...this.data.units];if(value&&!units.some(u=>u.code===value))units.push({code:value,label:value});return (blank?'<option value="">Choose unit</option>':'')+units.map(u=>`<option value="${esc(u.code)}" ${u.code===value?'selected':''}>${esc(u.label)}</option>`).join('');}
