  this.navigation.push({draft:clone(this.draft),dirty:this.dirty,tracking:clone(this.tracking),recipeHistory:clone(this.recipeHistory),pending:this.pending?clone(this.pending):null,price:this.price?clone(this.price):null,view:this.view,history:clone(this.history),search:this.$('#search').value,prompt:this.$('#prompt').value,includeRecipe:this.$('#include-recipe').checked,previewVisible:!this.$('#preview-card').hidden});
  this.view=this.componentView(target);this.history=[];this.openRecipe(target,true);this.$('#view-tab-'+this.view).focus();return true;
